SELECT
b.PROD_INS_ID prodId,
A.ORG_CODE orgCode,
b.PROD_NAME prodName,
A.REG_CODE regCode,
DATE_FORMAT(A.VDATE,'%Y-%m-%d') vdate,
DATE_FORMAT(A.MDATE,'%Y-%m-%d') mdate,
A.INVESTOR investor,
A.REMARK remark,
A.OPERATE_MODE operateMode,
DATE_FORMAT(d.RAISE_VDATE,'%Y-%m-%d') raiseVdate,
ifnull(c.send_status, #{sendStatus03,jdbcType=VARCHAR}) sendStatus,
c.send_remark sendRemark,
DATE_FORMAT(b.RAISE_PSTRDATE,'%Y-%m-%d') raisePstrDate,
DATE_FORMAT(b.RAISE_PENDDATE,'%Y-%m-%d') raisePendDate
FROM chb_prd_declare_info b
left join CHB_PRDRESIST_CODE A
on A.PRODID=b.PROD_INS_ID
left join INF_PRDRESISTCODE_SEND_INFO c
on b.PROD_INS_ID = c.prod_id
left join chb_prd_baseinfo d
on b.PROD_INS_ID = d.prod_id

	b.status !='D'


			#{prodid,jdbcType=VARCHAR}




			#{investor,jdbcType=VARCHAR}



		AND DATE_FORMAT(A.VDATE,'%Y-%m-%d') >= #{vdateStart}


		AND DATE_FORMAT(A.VDATE,'%Y-%m-%d') <= #{vdateEnd}


		AND DATE_FORMAT(A.MDATE,'%Y-%m-%d') >= #{mdateStart}


		AND DATE_FORMAT(A.MDATE,'%Y-%m-%d') <= #{mdateEnd}


		AND DATE_FORMAT(d.RAISE_VDATE,'%Y-%m-%d') >= #{raisevdateStart}


		AND DATE_FORMAT(d.RAISE_VDATE,'%Y-%m-%d') <= #{raisevdateEnd}



			#{regCode,jdbcType=VARCHAR}



		AND A.REG_CODE is null or A.REG_CODE=''




			#{orgCode,jdbcType=VARCHAR}






			#{key,jdbcType=VARCHAR}



		AND c.SEND_STATUS = #{sendStatus, jdbcType=VARCHAR}


ORDER BY A .UPDATE_TIME DESC,A .PRODID ASC

